div.script:
                        document.addEventListener('DOMContentLoaded', function() {
                            var startPointSelect = document.getElementById('start_point');
                            var endPointSelect = document.getElementById('end_point');
                            var upcomingHint = document.getElementById('upcomingRoutesHint');
                            var upcomingList = document.getElementById('upcomingRoutesList');

                            startPointSelect.addEventListener('change', function() {
                                var startPointId = this.value;

                                // Clear and disable end point
                                endPointSelect.innerHTML = 'Завантаження...';
                                endPointSelect.disabled = true;

                                // Hide upcoming routes hint
                                upcomingHint.style.display = 'none';
                                upcomingList.innerHTML = '';

                                if (!startPointId) {
                                    endPointSelect.innerHTML = 'Куди (необов\'язково)';
                                    return;
                                }

                                // Fetch available destinations
                                fetch('/bus-booking/get-destinations', {
                                    method: 'POST',
                                    headers: {
                                        'Content-Type': 'application/json',
                                    },
                                    body: JSON.stringify({
                                        jsonrpc: '2.0',
                                        method: 'call',
                                        params: { start_point_id: startPointId },
                                        id: Math.floor(Math.random() * 1000000)
                                    })
                                })
                                .then(function(response) { return response.json(); })
                                .then(function(data) {
                                    var destinations = data.result || [];

                                    endPointSelect.innerHTML = 'Куди (необов\'язково)';

                                    if (destinations.length === 0) {
                                        endPointSelect.innerHTML = 'Немає доступних напрямків';
                                        return;
                                    }

                                    destinations.forEach(function(dest) {
                                        var option = document.createElement('option');
                                        option.value = dest.id;
                                        option.textContent = dest.name;
                                        endPointSelect.appendChild(option);
                                    });

                                    endPointSelect.disabled = false;
                                })
                                .catch(function(error) {
                                    console.error('Error fetching destinations:', error);
                                    endPointSelect.innerHTML = 'Помилка завантаження';
                                });

                                // Fetch upcoming routes from this stop (hint)
                                fetch('/bus-booking/upcoming-routes', {
                                    method: 'POST',
                                    headers: {
                                        'Content-Type': 'application/json',
                                    },
                                    body: JSON.stringify({
                                        jsonrpc: '2.0',
                                        method: 'call',
                                        params: { start_point_id: startPointId },
                                        id: Math.floor(Math.random() * 1000000)
                                    })
                                })
                                .then(function(response) { return response.json(); })
                                .then(function(data) {
                                    var routes = data.result || [];

                                    if (routes.length === 0) {
                                        return;
                                    }

                                    var html = '';
                                    routes.forEach(function(route) {
                                        var dateLabel = route.is_today ? 'Сьогодні' : route.departure_date;
                                        html += '
';
                                        html += '' + route.departure_time + ' ';
                                        html += '' + dateLabel + ' → ';
                                        html += '' + route.destinations + '';
                                        html += '';
                                    });

                                    upcomingList.innerHTML = html;
                                    upcomingHint.style.display = 'block';
                                })
                                .catch(function(error) {
                                    console.error('Error fetching upcoming routes:', error);
                                });
                            });
                        });

t.script:
//
    document.addEventListener('DOMContentLoaded', function() {
        // Direct navigation to seat selection - NO intermediate step
        document.querySelectorAll('.route-card-v2').forEach(function(card) {
            card.addEventListener('click', function() {
                var routeId = this.getAttribute('data-route-id');
                if (routeId) {
                    window.location.href = '/bus-booking/book?route_id=' + routeId;
                }
            });
        });
    });
//

//
(function() {
    // --- STATE ---
    window.selectedSeats = [];
    window.pricePerSeat = 0;
    window.seatData = {};
    window.seatSelectionVisible = false;

    // --- SEAT TOGGLE FUNCTION ---
    window.toggleSeatSelection = function() {
        var panel = document.getElementById('seatSelectionPanel');
        if (!panel) return;

        window.seatSelectionVisible = !window.seatSelectionVisible;
        panel.style.display = window.seatSelectionVisible ? 'block' : 'none';
    };

    // --- VERIFICATION MODAL ---
    window.showVerificationModal = function() {
        var emailInput = document.getElementById('passenger_email');
        var phoneInput = document.getElementById('passenger_phone');
        var contact = (emailInput ? emailInput.value : '') || (phoneInput ? phoneInput.value : '') || '';

        var overlay = document.createElement('div');
        overlay.id = 'verificationModal';
        overlay.style.cssText = 'position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.7); display: flex; align-items: center; justify-content: center; z-index: 9999;';

        overlay.innerHTML = '<div style="background: white; border-radius: 16px; padding: 25px; max-width: 400px; width: 90%; text-align: center;">' +
            '<h3 style="margin: 0 0 15px; color: #333;">🔐 Підтвердження контакту</h3>' +
            '<p style="color: #666; margin-bottom: 15px;">Введіть email або телефон для підтвердження</p>' +
            '<div id="verifyStep1">' +
                '<input type="text" id="verifyContact" value="' + contact + '" placeholder="email@example.com або +380..." style="width: 100%; padding: 12px; border: 2px solid #ddd; border-radius: 8px; font-size: 16px; box-sizing: border-box; margin-bottom: 15px;"/>' +
                '<button onclick="window.sendVerificationCode()" style="width: 100%; padding: 12px; background: linear-gradient(135deg, #43a047, #2e7d32); color: white; border: none; border-radius: 8px; font-size: 16px; cursor: pointer;">📧 Надіслати код</button>' +
            '</div>' +
            '<div id="verifyStep2" style="display: none;">' +
                '<p style="color: #666; margin-bottom: 10px;">Код надіслано на <strong id="verifyContactDisplay"></strong></p>' +
                '<input type="text" id="verifyCode" maxlength="6" placeholder="000000" style="width: 100%; padding: 12px; border: 2px solid #ddd; border-radius: 8px; font-size: 24px; text-align: center; letter-spacing: 8px; box-sizing: border-box; margin-bottom: 15px;"/>' +
                '<button onclick="window.verifyCode()" style="width: 100%; padding: 12px; background: linear-gradient(135deg, #43a047, #2e7d32); color: white; border: none; border-radius: 8px; font-size: 16px; cursor: pointer; margin-bottom: 10px;">✅ Підтвердити</button>' +
                '<button onclick="document.getElementById(\'verifyStep2\').style.display=\'none\'; document.getElementById(\'verifyStep1\').style.display=\'block\';" style="width: 100%; padding: 10px; background: #f0f0f0; color: #333; border: none; border-radius: 8px; font-size: 14px; cursor: pointer;">← Змінити контакт</button>' +
            '</div>' +
            '<button onclick="window.closeVerificationModal()" style="margin-top: 15px; padding: 10px 20px; background: #f0f0f0; color: #333; border: none; border-radius: 8px; cursor: pointer;">✕ Закрити</button>' +
        '</div>';

        document.body.appendChild(overlay);
    };

    window.closeVerificationModal = function() {
        var modal = document.getElementById('verificationModal');
        if (modal) modal.remove();
    };

    window.verificationContact = '';

    window.sendVerificationCode = function() {
        var contactInput = document.getElementById('verifyContact');
        if (!contactInput || !contactInput.value.trim()) {
            alert('Введіть email або телефон');
            return;
        }

        window.verificationContact = contactInput.value.trim();

        fetch('/bus-booking/api/send-verification', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {contact: window.verificationContact}, id: 1})
        })
        .then(function(r) { return r.json(); })
        .then(function(json) {
            if (json.result && json.result.success) {
                document.getElementById('verifyStep1').style.display = 'none';
                document.getElementById('verifyStep2').style.display = 'block';
                document.getElementById('verifyContactDisplay').textContent = window.verificationContact;
            } else {
                alert(json.result ? json.result.error : 'Помилка надсилання');
            }
        })
        .catch(function() {
            alert('Помилка з\'єднання');
        });
    };

    window.verifyCode = function() {
        var codeInput = document.getElementById('verifyCode');
        if (!codeInput || codeInput.value.length !== 6) {
            alert('Введіть 6-значний код');
            return;
        }

        fetch('/bus-booking/api/verify-code', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {contact: window.verificationContact, code: codeInput.value}, id: 1})
        })
        .then(function(r) { return r.json(); })
        .then(function(json) {
            if (json.result && json.result.success) {
                alert('✅ Контакт підтверджено!');
                // Fill in verified contact
                var isEmail = window.verificationContact.indexOf('@') !== -1;
                if (isEmail) {
                    document.getElementById('passenger_email').value = window.verificationContact;
                } else {
                    document.getElementById('passenger_phone').value = window.verificationContact;
                }
                window.closeVerificationModal();
            } else {
                alert(json.result ? json.result.error : 'Невірний код');
            }
        })
        .catch(function() {
            alert('Помилка з\'єднання');
        });
    };

    // --- CORE FUNCTIONS ---
    window.modernBusBooking_toggleSeat = function(seatId) {
        try {
            var seat = document.getElementById('seat_' + seatId);
            if (!seat || seat.classList.contains('booked') || seat.classList.contains('reserved')) return;

            var index = window.selectedSeats.indexOf(seatId);
            if (index > -1) {
                window.selectedSeats.splice(index, 1);
                seat.classList.remove('selected');
                seat.classList.add('available');
            } else {
                window.selectedSeats.push(seatId);
                seat.classList.add('selected');
                seat.classList.remove('available');
            }
            window.updateSelectedSeatsDisplay();
        } catch (e) {
            console.error('Error in toggleSeat:', e);
        }
    };

    window.updateSelectedSeatsDisplay = function() {
        var info = document.getElementById('selectedSeatsInfo');
        var seatDisplay = document.getElementById('selectedSeatDisplay');
        if (!info) return;

        var list = document.getElementById('selectedSeatsList');
        var count = document.getElementById('seatCount');
        var totalPriceEl = document.getElementById('totalPrice');
        var hidden = document.getElementById('selectedSeats');

        // Convert seat IDs to readable format (e.g., "1_1" -> "1A")
        var readableSeats = window.selectedSeats.map(function(sid) {
            var parts = sid.split('_');
            var row = parts[0];
            var col = parseInt(parts[1]);
            var colLetter = ['A', 'B', 'C', 'D'][col - 1] || col;
            return row + colLetter;
        });

        if (window.selectedSeats.length > 0) {
            info.style.display = 'block';
            list.textContent = readableSeats.join(', ');
            hidden.value = window.selectedSeats.join(',');
            count.textContent = window.selectedSeats.length;
            totalPriceEl.textContent = Math.round(window.pricePerSeat * window.selectedSeats.length) + ' ₴';
            // Update toggle display
            if (seatDisplay) {
                seatDisplay.textContent = readableSeats.join(', ');
                seatDisplay.style.background = 'linear-gradient(135deg, #1976d2, #1565c0)';
            }
        } else {
            info.style.display = 'none';
            hidden.value = '';
            // Reset to AUTO
            if (seatDisplay) {
                seatDisplay.textContent = 'AUTO';
                seatDisplay.style.background = 'linear-gradient(135deg, #43a047, #2e7d32)';
            }
        }
    };

    // --- INITIALIZATION ---
    function initialize() {
        var priceEl = document.getElementById('priceData');
        if (priceEl) {
            window.pricePerSeat = parseFloat(priceEl.dataset.price) || 0;
        }

        var seatDataEl = document.getElementById('seatDataJson');
        if (seatDataEl) {
            try {
                window.seatData = JSON.parse(seatDataEl.textContent || '{}');
            } catch (e) {
                console.error('Failed to parse seat data:', e);
            }
        }

        // Mark booked seats (paid)
        if (window.seatData.booked_seat) {
            window.seatData.booked_seat.forEach(function(sid) {
                var s = document.getElementById('seat_' + sid);
                if (s) {
                    s.classList.remove('available');
                    s.classList.add('booked');
                    s.innerHTML = '<span class="seat-icon">👤</span>';
                    s.onclick = null;
                }
            });
        }
        // Mark reserved seats (unpaid)
        if (window.seatData.reserved_seat) {
            window.seatData.reserved_seat.forEach(function(sid) {
                var s = document.getElementById('seat_' + sid);
                if (s) {
                    s.classList.remove('available');
                    s.classList.add('reserved');
                    s.innerHTML = '<span class="seat-icon">⏳</span>';
                    s.onclick = null;
                }
            });
        }

        // Initialize dropping point selector
        var droppingSelect = document.getElementById('droppingPointSelect');
        if (droppingSelect) {
            droppingSelect.addEventListener('change', function() {
                var selectedOption = this.options[this.selectedIndex];
                var newPrice = parseFloat(selectedOption.dataset.price) || 0;
                var newId = this.value;

                // Update global price
                window.pricePerSeat = newPrice;

                // Update hidden input
                var hiddenInput = document.getElementById('dropping_point');
                if (hiddenInput) hiddenInput.value = newId;

                // Update display
                var badge = document.querySelector('.route-price-badge');
                if (badge) badge.textContent = Math.round(newPrice) + ' ₴';

                // Recalculate totals
                window.updateSelectedSeatsDisplay();
            });
        }
    }

    document.addEventListener('DOMContentLoaded', initialize);

    // --- FORM ACTIONS ---
    function validateForm() {
        // Sedadlo není povinné - může být AUTO
        // Pouze kontrola, že email a telefon jsou vyplněny
        var email = document.getElementById('passenger_email').value.trim();
        var phone = document.getElementById('passenger_phone').value.trim();

        if (!email) {
            alert('Vyplňte prosím email');
            return false;
        }
        if (!phone) {
            alert('Vyplňte prosím telefon');
            return false;
        }
        return true;
    }

    window.reserveSeats = function() {
        if (!validateForm()) return;
        var formData = new FormData(document.getElementById('bookingForm'));
        var data = {
            route_id: document.getElementById('routeId').value,
            selected_seats: window.selectedSeats,
            passenger_name: formData.get('passenger_name'),
            passenger_email: formData.get('passenger_email'),
            passenger_phone: formData.get('passenger_phone'),
            boarding_point: formData.get('boarding_point'),
            dropping_point: formData.get('dropping_point')
        };
        fetch('/bus-booking/reserve', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: data })
        })
        .then(function(response) { return response.json(); })
        .then(function(result) {
            if (result.result && result.result.success) {
                window.location.href = result.result.redirect_url;
            } else {
                alert(result.result ? result.result.message : 'Chyba při rezervaci');
            }
        })
        .catch(function(error) {
            console.error('Error:', error);
            alert('Помилка при створенні резервації');
        });
    };

    window.buyTickets = function() {
        if (!validateForm()) return;
        var formData = new FormData(document.getElementById('bookingForm'));
        var data = {
            route_id: document.getElementById('routeId').value,
            selected_seats: window.selectedSeats,
            passenger_name: formData.get('passenger_name'),
            passenger_email: formData.get('passenger_email'),
            passenger_phone: formData.get('passenger_phone'),
            boarding_point: formData.get('boarding_point'),
            dropping_point: formData.get('dropping_point')
        };
        fetch('/bus-booking/reserve', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ jsonrpc: '2.0', method: 'call', params: data })
        })
        .then(function(response) { return response.json(); })
        .then(function(result) {
            if (result.result && result.result.success) {
                var rid = result.result.reservation_id;
                if (rid) {
                    window.location.href = '/bus-booking/pay?reservation_id=' + rid;
                } else if (result.result.redirect_url) {
                    window.location.href = result.result.redirect_url;
                } else {
                    alert('Rezervace proběhla, ale chybí ID.');
                }
            } else {
                alert(result.result ? result.result.message : 'Chyba při nákupu');
            }
        })
        .catch(function(error) {
            console.error('Error:', error);
            alert('Помилка при створенні резервації');
        });
    };

})();
//

//
    // Автоматичне перенаправлення через 10 секунд
    setTimeout(function() {
        // Якщо користувач не встигне натиснути, перенаправляємо на головну
        if (!document.hidden) {
            console.log('Перенаправлення на головну сторінку...');
            // window.location.href = '/bus-booking';
        }
    }, 10000);

    // Показати сповіщення про успішний платіж
    if (typeof odoo !== 'undefined' &amp;&amp; odoo.notification) {
        odoo.notification.notify({
            title: 'Платіж успішний!',
            message: 'Ваш квиток оплачено та готовий до використання.',
            type: 'success'
        });
    }
//

xpath.script:
document.addEventListener('DOMContentLoaded', function() {
    // Fix back buttons on checkout and payment pages
    if (window.location.pathname.includes('/shop/checkout') ||
        window.location.pathname.includes('/shop/payment')) {

        // Find all links pointing to cart
        var cartLinks = document.querySelectorAll('a[href*="/shop/cart"]');
        cartLinks.forEach(function(link) {
            link.href = '/bus-booking/back';
            link.innerHTML = ' Zpět na výběr míst';
        });

        // Also fix "Back to cart" text
        var backLinks = document.querySelectorAll('a.btn-link');
        backLinks.forEach(function(link) {
            if (link.textContent.includes('Back to cart') ||
                link.textContent.includes('cart') ||
                link.href.includes('/shop/cart')) {
                link.href = '/bus-booking/back';
                link.innerHTML = ' Zpět na výběr míst';
            }
        });
    }
});
